UPDATE sys_role
SET role_code = #{roleCode},
    role_name = #{roleName},
    status = #{status}
WHERE id = #{id}

mapper.select:
SELECT id, role_code, role_name, status, create_at
FROM sys_role
WHERE id = #{id}

SELECT id, role_code, role_name, status, create_at
FROM sys_role
WHERE role_code = #{roleCode}

SELECT id, role_code, role_name, status, create_at FROM sys_role
(role_code LIKE CONCAT('%', #{keyword}, '%') OR role_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC LIMIT #{size} OFFSET #{offset}
